def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]

    remaining = 100 - n
    if remaining <= 0:
        return 'C'

    # Count defects.
    opp_d = 0
    my_d = 0
    for x in opp:
        if x == 'D':
            opp_d += 1
    for x in me:
        if x == 'D':
            my_d += 1
    opp_c = n - opp_d

    # Detect pure or near-pure defectors quickly.
    if n >= 6 and opp_d >= n - 1:
        return 'D'
    if n >= 10 and opp_d * 4 >= n * 3:
        # Heavily defective: defect, but rare probe to test for change.
        if n >= 2 and opp[-1] == 'C' and opp[-2] == 'C':
            return 'C'
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Detect pure cooperators: cooperate to build mutual reward,
    # but take endgame exploitation only when enough remains.
    if opp_d == 0:
        if remaining <= 2 and n >= 90:
            return 'D'
        return 'C'

    # Early game: cooperate more, respond gently to a single initial defection.
    if n <= 3:
        if opp_d >= 2:
            return 'D'
        return 'C'

    # Recent behavior windows.
    w = min(n, 10)
    recent_opp = opp[-w:]
    recent_my = me[-w:]
    r_opp_d = 0
    r_my_d = 0
    for x in recent_opp:
        if x == 'D':
            r_opp_d += 1
    for x in recent_my:
        if x == 'D':
            r_my_d += 1

    # If opponent just cooperated after defects, reward cooperation.
    if last_opp == 'C':
        if opp_d * 3 <= n:
            return 'C'
        if r_opp_d * 2 <= w:
            return 'C'
        if last_me == 'D':
            return 'C'
        return 'C'

    # Opponent just defected.
    # If we are already in repeated mutual defection, try to restore cooperation sometimes.
    if last_me == 'D' and last_opp == 'D':
        if r_opp_d >= 2 and r_my_d >= 2:
            if remaining > 3 and rng.random() < 0.35:
                return 'C'
            return 'D'

    # If opponent's recent defection rate is high, retaliate.
    if r_opp_d * 3 >= w:
        return 'D'

    # If opponent's recent defection rate moderate, retaliate but forgive sometimes.
    if r_opp_d * 2 >= w:
        if remaining <= 3:
            return 'D'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # If opponent defected only once recently, retaliate once then return.
    if r_opp_d == 1:
        if last_me == 'C':
            return 'D'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Default: cooperate.
    return 'C'
